export default function WallOfLoveSection() {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const heartBtn = containerRef.current?.querySelector("button");
    if (heartBtn) {
      heartBtn.addEventListener("click", () => {
        const countSpan = heartBtn.querySelector("span");
        if (countSpan && countSpan.textContent) {
          const num = parseInt(countSpan.textContent.replace(/,/g, ''), 10) || 0;
          countSpan.textContent = (num + 1).toLocaleString();
        }
      });
    }
  }, []);

  return <div ref={containerRef} className="contents" dangerouslySetInnerHTML={{ __html: WOL_HTML }} />;
}
